{"command": "cd /workdir && python3 -c "
import json
d = json.load(open('output/analysis_results.json'))
# structure check
assert set(d) == {'eda_results','hypothesis_test_results'}
e = d['eda_results']; h = d['hypothesis_test_results']
assert set(e) == {'sales_stats_by_region','unique_product_count'}
for r in ['Region A','Region B','Region C']:
    assert set(e['sales_stats_by_region'][r]) == {'mean_sales','median_sales','std_dev_sales'}
assert isinstance(e['unique_product_count'], int)
assert set(h) == {'hypothesis','assumption_checks','chosen_test','test_justification','t_statistic','u_statistic','p_value','confidence_interval_lower','confidence_interval_upper','conclusion'}
print('JSON valid, structure OK')
print('Mann-Whitney: t_statistic null =', h['t_statistic'] is None, '| CI null =', h['confidence_interval_lower'] is None and h['confidence_interval_upper'] is None)
""}

